export interface ActionbarButtonConfig {
  name: string;
  icon: string;
  iconSize: string;
  iconType: string;
  mode: string;
  type: string;
  addcls: string;
}

export const ACTIONBAR_EVENTS = {
  OPEN: 'ACTION_OPEN',
  CLOSE: 'ACTION_CLOSE',
} as const;

export type ActionbarEvent = typeof ACTIONBAR_EVENTS[keyof typeof ACTIONBAR_EVENTS];

export const ACTIONBAR_ACTION_TYPES = {
  CB: 'CB',
  CO: 'CO',
  ASIGN: 'ASIGN',
  COPY: 'COPY',
  CUT: 'CUT',
  DOWNLOAD: 'DOWNLOAD',
  PRESENTATION: 'PRESENTATION',
  HYPERLINK_DOC: 'HYPERLINK-DOC',
} as const;

export type ActionbarActionType = (typeof ACTIONBAR_ACTION_TYPES)[keyof typeof ACTIONBAR_ACTION_TYPES];

export const ACTIONBAR_ACTIONTYPE_GROUPS = {
  CB_ONLY: [ACTIONBAR_ACTION_TYPES.CB] as readonly string[],
  CB_OR_CO: [ACTIONBAR_ACTION_TYPES.CB, ACTIONBAR_ACTION_TYPES.CO] as readonly string[],
  DOWNLOAD: [ACTIONBAR_ACTION_TYPES.DOWNLOAD] as readonly string[],
  HYPERLINK_DOC: [ACTIONBAR_ACTION_TYPES.HYPERLINK_DOC] as readonly string[],
} as const;

export const ACTIONBAR_FOLDER_TYPES = {
  CB: 'CB',
  CO: 'CO',
  MB: 'MB',
} as const;

export type ActionbarFolderType = (typeof ACTIONBAR_FOLDER_TYPES)[keyof typeof ACTIONBAR_FOLDER_TYPES];

export const ACTIONBAR_CLOSE_ACTION_TYPES = ['EXPOERT', 'UNDO', 'Unassign', 'CONV', 'PRESENTATION'] as const;

export type ActionbarCloseActionType = (typeof ACTIONBAR_CLOSE_ACTION_TYPES)[number];

