import { ChangeDetectorRef, Component, EventEmitter, Input, input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { MyfileService } from '../../services/myfile/myfile.service';
import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { DndDraggableDirective, DndDropEvent, DndDropzoneDirective, DndHandleDirective, DndPlaceholderRefDirective } from 'ngx-drag-drop';
import { DragDropModule } from '@angular/cdk/drag-drop';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { TruncateTooltipDirective } from '../../directive/truncate-tooltip.directive';

@Component({
  selector: 'downloadtable',
  standalone: true,
  imports: [CommonModule, IconComponent, MatTooltipModule, ScrollingModule, NgScrollbarModule,
    DndDropzoneDirective, DndPlaceholderRefDirective, DndDraggableDirective, DndHandleDirective, DragDropModule,
    TruncateTooltipDirective
  ],
  templateUrl: './downloadtable.component.html',
  styleUrl: './downloadtable.component.scss'
})
export class DownloadtableComponent {

  @Output() onEvent: EventEmitter<toolEvents> = new EventEmitter();
  @ViewChild(CdkVirtualScrollViewport) viewport: CdkVirtualScrollViewport;
  @Input() jFolders: string;
  @Input() jFiles: string;
  @Input() nSectionid: string;
  @Input() nCaseid: string;
  nBundleid: any;
  brdcrumb: any = [];
  filelist: any[] = [];
  fileSerial: any[];
  draggedItem: any = null;
  @Input() nDTaskid: string;
  viewportHeight: number = 440;
  constructor(private mfService: MyfileService, private cdr: ChangeDetectorRef) {

  }

  ngOnInit() {
    // this.getDownloadFiles();
  }



  async ngOnChanges(changes: SimpleChanges) {
    debugger;
    if (!this.nBundleid) {
      this.getDownloadFiles();
    }
  }


  changeBrdcrumb(index) {
    this.brdcrumb = this.brdcrumb.filter((e, i) => i <= index);
    this.nBundleid = this.brdcrumb.length ? this.brdcrumb[this.brdcrumb.length - 1]["nBundleid"] : 0;
    this.getDownloadFiles(this.nBundleid);
  }

  trackByFruit(index: number, item) {
    return item.nBundleid;
  }



  async getDownloadFiles(nBundleid?) {
    const res = await this.mfService.getDownloadFiles(this.nDTaskid || null, this.nCaseid, this.nSectionid, this.jFolders, this.jFiles, nBundleid || null)
    this.filelist = res;

    if (this.filelist.length > 8) {
      this.viewportHeight = 440;
    } else {
      this.viewportHeight = this.filelist.length * 54;
    }


    if (res && res.length)
      this.nDTaskid = res[0]['nDTaskid'] || 0;
    setTimeout(() => {     
      this.viewport?.checkViewportSize(); 
    });
    
    this.onEvent.emit({ event: 'nDTaskid', data: { nDTaskid: this.nDTaskid } })
  }


  onDragStart(event: DragEvent, item: any) {
    this.draggedItem = item;
  }

  onDragEnd(event: DragEvent) {
    this.draggedItem = null;
  }

  onDrop2(event: DndDropEvent, list: any[]) {
    debugger;

    if (!this.draggedItem || !this.viewport) return;

    let dropIndex = event.index;

    if (typeof dropIndex === 'undefined') {
      dropIndex = list.length;
    } else {
      const firstRenderedIndex = this.viewport.getRenderedRange().start;
      dropIndex += firstRenderedIndex;
    }

    let draggedIndex = 0;
    if (this.draggedItem.nBundledetailid) {
      draggedIndex = list.findIndex(f => f.nBundledetailid === this.draggedItem.nBundledetailid);
    } else {
      draggedIndex = list.findIndex(f => f.nBundleid === this.draggedItem.nBundleid);
    }

    if (draggedIndex !== -1) {
      list.splice(draggedIndex, 1);
      if (draggedIndex < dropIndex) {
        dropIndex--;
      }
    }

    list.splice(dropIndex, 0, this.draggedItem);

    console.log(`Moved item ${this.draggedItem.id} to index ${dropIndex}`);
    // Store the current scroll position
    const scrollPosition = this.viewport.measureScrollOffset();
    this.updateFileSerial(this.draggedItem.nBundleid, this.draggedItem.nBundledetailid, dropIndex)
    this.draggedItem = null;
    // Create a new reference for the list to trigger change detection
    this.filelist = [...this.filelist];

    // Use setTimeout to allow the view to update before adjusting the scroll position
    setTimeout(() => {
      this.viewport!.checkViewportSize();
      this.viewport!.scrollToOffset(scrollPosition);
      this.cdr.detectChanges();
    });
  }

  async updateFileSerial(nBundleid, nBundledetailid, nNIndex) {
    debugger
    try {
      await this.mfService.getDownloadUpdateSerial(this.nDTaskid || null, nBundleid || null, nBundledetailid || null, nNIndex)
    } catch (error) {
    }
  }

  openFolder(item) {
    this.brdcrumb.push({ nBundleid: item.nBundleid, cBundlename: item.cName });
    this.nBundleid = item.nBundleid;
    this.getDownloadFiles(item.nBundleid)
  }
}
