import { Component, Inject, OnDestroy, OnInit } from '@angular/core';
import { ButtonComponent } from '../button/button.component';
import { IconComponent } from '../icon/icon.component';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { SectionRes } from '../../../adminpanel/interfaces/bundlemanage.interface';
import { CommunicationService } from '../../services/communication/communication.service';
import { BundlemanageService } from '../../../adminpanel/services/bundle-manage/bundlemanage.service';
import { DownloadtableComponent } from '../downloadtable/downloadtable.component';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../core/services/socket/socket.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { HeaderService } from '../../../core/services/header/header.service';
import {
  ACTIONBAR_ACTION_TYPES,
  ACTIONBAR_ACTIONTYPE_GROUPS,
  ACTIONBAR_CLOSE_ACTION_TYPES,
  ACTIONBAR_FOLDER_TYPES,
} from '../../interfaces/actionbar.interface';
import { MYFILES_CS_EVENTS, MYFILES_CS_TYPES } from '../../../userpanel/utility/user-panel-constants';
import { TranslateModule } from '@ngx-translate/core';

const ACTIONBAR_EVENTS = {
  CHANGE_SECTION: 'CHANGE-SECTION',
} as const;

const ACTIONBAR_DIALOG_RESULTS = {
  CLOSE: 'Close',
  DELETE: 'Delete',
} as const;

const ACTIONBAR_DOWNLOAD_STATUS = {
  IN_PROGRESS: 'P',
  FINISHED: 'F',
  COMPLETE: 'C',
} as const;

const ACTIONBAR_DOWNLOAD_TABLE_EVENTS = {
  TASK_ID: 'nDTaskid',
} as const;

interface ActionbarDialogData {
  files?: number;
  folders?: number;
  isadmin?: boolean;
  nCaseid?: string;
  nSectionid?: string;
  assignTodef?: string;
  jFiles?: string;
  jFolders?: string;
  iconSize?: string;
  buttons?: Array<{ name: string; type: string; mode?: string; addcls?: string; icon?: string; iconType?: string }>;
  pasteFiles?: (type: string | null) => void;
  assignFiles?: (type: string | null) => void;
  resetpath?: () => void;
  getSelectedFolder?: () => unknown[];
}

interface DownloadSocketEvent {
  data?: {
    type?: string;
    message?: string;
    nBundledetailid?: string;
    cName?: string;
  };
}

interface DownloadTableEvent {
  event?: string;
  data?: { nDTaskid?: string };
}

interface CommunicationEvent {
  event?: string;
}

@Component({
  selector: 'app-actionbar',
  standalone: true,
  imports: [ButtonComponent, IconComponent, CommonModule, MatMenuModule, DownloadtableComponent, TranslateModule],
  templateUrl: './actionbar.component.html',
  styleUrl: './actionbar.component.scss'
})
export class ActionbarComponent implements OnInit, OnDestroy {
  readonly ACTIONBAR_ACTIONTYPE_GROUPS = ACTIONBAR_ACTIONTYPE_GROUPS;

  files = 0;
  folders = 0;
  type: string | null = null;
  actiontype = '';
  isUndo = false;
  progress = false;
  isdownload = false;
  isadmin = false;
  sections: SectionRes[] = [];
  nCaseid = '';
  assignTodef = '';
  defsection?: SectionRes;
  showList = false;
  nSectionid = '';
  jFolders = '';
  jFiles = '';
  nDTaskid = '';
  isDownloding = false;
  responceMsg = '';
  indexStatus = '';
  isMeexpand: boolean = false;
  isDownloadStarted = false;
  downloadLoading = false;
  confirmation = false;

  private readonly socketSubscription: Subscription;
  private evsubscription?: Subscription;

  constructor(
    private readonly dialogRef: MatDialogRef<ActionbarComponent>,
    @Inject(MAT_DIALOG_DATA) public data: ActionbarDialogData,
    private readonly cs: CommunicationService,
    private readonly bmService: BundlemanageService,
    private readonly ss: SocketService,
    private readonly cf: CommonfunctionService,
    private readonly hs: HeaderService,
  ) {
    this.files = data?.files ?? 0;
    this.folders = data?.folders ?? 0;
    this.isadmin = data?.isadmin ?? false;
    this.nCaseid = data?.nCaseid ?? '';
    this.nSectionid = data?.nSectionid ?? '';
    this.assignTodef = data?.assignTodef ?? '';
    this.jFiles = data?.jFiles ?? '';
    this.jFolders = data?.jFolders ?? '';

    this.socketSubscription = this.ss.getDownload().subscribe((res: DownloadSocketEvent) => {
      const type = res?.data?.type ?? '';
      this.indexStatus = type;

      if (type !== ACTIONBAR_DOWNLOAD_STATUS.FINISHED && type !== ACTIONBAR_DOWNLOAD_STATUS.COMPLETE) {
        this.responceMsg = res?.data?.message ?? '';
      }

      if (type === ACTIONBAR_DOWNLOAD_STATUS.FINISHED) {
        this.isDownloding = false;
        this.responceMsg = res?.data?.message ?? '';
        this.dialogRef.close();
      }

      if (type === ACTIONBAR_DOWNLOAD_STATUS.COMPLETE) {
        this.isDownloding = false;
        this.dialogRef.close({
          isSave: true,
          nBundledetailid: res?.data?.nBundledetailid,
          cName: res?.data?.cName,
        });
      }
    });
  }


  ngOnInit(): void {
    if (this.isadmin) {
      void this.getSection();
    }

    this.evsubscription = this.cs.functionCalled$.subscribe((data: CommunicationEvent | null) => {
      if (data?.event === MYFILES_CS_EVENTS.DOWNLOAD_STARTED) {
        this.isDownloadStarted = true;
        this.downloadLoading = false;
      } else if (data?.event === MYFILES_CS_EVENTS.DOWNLOAD_FAILED) {
        this.isDownloadStarted = false;
        this.downloadLoading = false;
      }
    });
  }

  ngOnDestroy(): void {
    this.isDownloadStarted = false;
    this.cs.callFunction({ type: MYFILES_CS_TYPES.CUT_COPY_EVENT, isCopy: false });
    this.socketSubscription.unsubscribe();
    this.evsubscription?.unsubscribe();
  }

  close(): void {
    if (this.actiontype === ACTIONBAR_ACTION_TYPES.CB && this.hs.isGlobalSearch) {
      this.cs.callFunction({ type: ACTIONBAR_EVENTS.CHANGE_SECTION, cFoldertype: ACTIONBAR_FOLDER_TYPES.MB });
    }
    this.type = null;
    this.dialogRef.close(ACTIONBAR_DIALOG_RESULTS.CLOSE);
  }

  delete(): void {
    this.dialogRef.close(ACTIONBAR_DIALOG_RESULTS.DELETE);
  }

  changeSection(x: Partial<SectionRes>): void {
    if (x?.nSectionid) {
      this.actiontype = ACTIONBAR_ACTION_TYPES.CO;
      this.type = x.cFolder ?? null;
    }
    this.cs.callFunction({
      type: ACTIONBAR_EVENTS.CHANGE_SECTION,
      nSectionid: x?.nSectionid,
      cFoldertype: x?.cFoldertype,
    });
  }

  async getSection(): Promise<void> {
    if (!this.sections.length) {
      const res = await this.bmService.getSections(this.nCaseid);
      this.sections = res ?? [];
      if (this.assignTodef) {
        this.defsection = this.sections.find((e) => e.nSectionid === this.assignTodef);
      }
    }
  }

  btnclick(type: string, actiontype: string): void {
    if (this.shouldFetchSectionsForCore(actiontype)) {
      void this.getSection();
      return;
    }

    this.applyDefaultSectionIfNeeded();
    this.actiontype = actiontype;

    if (type === 'Delete') {
      this.confirmation = true;
      return;
    }

    if (type === 'Paste') {
      this.handlePaste();
      return;
    }

    if (this.shouldCloseDialogForAction(actiontype)) {
      this.dialogRef.close(actiontype);
      return;
    }

    if (actiontype === ACTIONBAR_ACTION_TYPES.ASIGN) {
      this.handleAssign();
      return;
    }

    this.setTypeAndMaybeResetPath(type);

    if (actiontype === ACTIONBAR_ACTION_TYPES.COPY || actiontype === ACTIONBAR_ACTION_TYPES.CUT) {
      this.cs.callFunction({ type: MYFILES_CS_TYPES.CUT_COPY_EVENT, isCopy: true });
    }

    if (actiontype === ACTIONBAR_ACTION_TYPES.HYPERLINK_DOC) {
      this.downloadWithLinkfile();
    }
  }

  private shouldFetchSectionsForCore(actiontype: string): boolean {
    return actiontype === ACTIONBAR_ACTION_TYPES.CO && !this.assignTodef;
  }

  private applyDefaultSectionIfNeeded(): void {
    if (this.assignTodef && this.defsection) {
      this.changeSection(this.defsection);
    }
  }

  private shouldCloseDialogForAction(actiontype: string): boolean {
    return (ACTIONBAR_CLOSE_ACTION_TYPES as readonly string[]).includes(actiontype);
  }

  private handlePaste(): void {
    if (typeof this.data.pasteFiles !== 'function') {
      return;
    }
    if (this.progress) {
      return;
    }
    this.progress = true;
    this.data.pasteFiles(this.type);
  }

  private handleAssign(): void {
    if (typeof this.data.assignFiles !== 'function') {
      return;
    }
    if (this.progress) {
      return;
    }
    this.progress = true;
    this.data.assignFiles(this.type);
  }

  private setTypeAndMaybeResetPath(type: string): void {
    this.type = type;
    if (this.actiontype === ACTIONBAR_ACTION_TYPES.CB) {
      this.data.resetpath?.();
      this.changeSection({ cFoldertype: ACTIONBAR_FOLDER_TYPES.CB });
    }
  }

  downloadWithLinkfile(): void {
    this.downloadLoading = true;
    this.cs.callFunction(MYFILES_CS_EVENTS.HYPERLINK_DOC);
  }

  downloadFiles(): void {
    if (this.indexStatus === ACTIONBAR_DOWNLOAD_STATUS.IN_PROGRESS) {
      return;
    }
    this.downloadLoading = true;
    this.cs.callFunction(MYFILES_CS_EVENTS.DOWNLOAD_FILE);
  }

  getSelectedFolder(): boolean {
    return !(this.data.getSelectedFolder?.()?.length ?? 0);
  }

  goback(): void {
    if (this.confirmation) {
      this.confirmation = false;
      return;
    }

    this.close();
  }

  downloadEvent(e: DownloadTableEvent): void {
    if (e?.event === ACTIONBAR_DOWNLOAD_TABLE_EVENTS.TASK_ID) {
      this.nDTaskid = e?.data?.nDTaskid ?? '';
    }
  }


  viewDownloading(): void {
    this.cf.goto('myfiles/download', { id: this.nCaseid });
  }
}
